import Root from "./1Adding Interactivity/5UpdatingArrays"
import Sub from "./subReLearn"
import "./ReLearn.css"

export default function () {
  return (
    <>
    <Immer/>
    </>
  );
}

import { useState } from "react"
import { useImmer } from "use-immer"

const initialNum = [{val: 0}]
export function Immer() {
  const [num, setNum] = useImmer(initialNum)
  const [otherNum, setOtherNum] = useImmer(initialNum)
  function change() {
    // Cara useState yang benar untuk Array of Objects:
    // Gunakan .map() untuk menyalin array sekaligus objek di dalamnya agar aman
    const nextNum = num.map((item, index) => {
      if (index === 0) {
        return { ...item, val: 5 } // Buat objek baru untuk index ke-0
      }
      return item
    })
    setNum(nextNum)
  }

  function otherChange() {
    // Kode otherChange kamu yang lama (ini trik merusak memori pusat yang kamu mau)
    const numbre = [...otherNum]
    const newNum = numbre[0]
    newNum.val = 10
    setOtherNum(numbre)
  }
  return (
    <>
    <Elem content={num} func={change}/>
    <Elem content={otherNum} func={otherChange}/>
    </>
  );
}

function Elem({content, func}) {
  return content.map(e => <>
  {e.val} <button onClick={func}>click</button> <br/>
  </>)
}


// http://localhost:3000
